# Create gradient data for speciation
speciation_gradient <- create_gradient_polygons(time, maxHPD, minHPD, rate, "#4c4cec")

# Create data frames for speciation plot
speciation_data <- data.frame(
  time = time,
  rate = rate,
  minHPD = minHPD,
  maxHPD = maxHPD
)
# Remove rows with NA in 'rate' column
speciation_data <- speciation_data[!is.na(speciation_data$rate), ]

# Speciation Rate Plot with gradient polygons
p1 <- ggplot() +
  geom_line(data = speciation_data, aes(x = time, y = rate), 
            color = '#4c4cec', size = 1.2) +
  geom_polygon(data = speciation_gradient, 
            aes(x = x, y = y, group = group, alpha = alpha_val), 
            fill = '#4c4cec', color = NA) +
  geom_vline(xintercept = perm_trias_extinction, color = "red", linetype = "dashed") +
  geom_vline(xintercept = guadalupian_extinction, color = "red", linetype = "dashed") +
  coord_geo(xlim = c(-300, -200),
            expand = FALSE,
            clip = "on",
            dat = list("international epochs", "international periods"),
            abbrv = list(TRUE, FALSE),
            pos = list("bottom", "bottom"),
            alpha = 1,
            height = unit(1, "line"),
            rot = 0,
            size = "auto",
            neg = TRUE) +
  scale_x_continuous(breaks = x_ticks, labels = x_tick_labels, limits = c(-298.420319, -201.732195)) +
  scale_y_continuous(limits = c(0, 3)) +
  scale_alpha_identity() +  # This tells ggplot to use the alpha values directly
  labs(x = 'Time', y = 'Speciation rate', 
       title = 'Synapsida RJMCMC No Predictors') +
  base_theme

